/* @lc app=leetcode id=3218 lang=kotlin */ class Solution { fun minimumCost(m: Int, n: Int, horizontalCut: IntArray, verticalCut: IntArray): Int = (horizontalCut.map { it to 'H' } + verticalCut.map { it to 'V' }).sortedByDescending { it.first }.fold(Triple(1, 1, 0)) { (hp, vp, total), (cost, type) -> if (type == 'H') Triple(hp + 1, vp, total + cost * vp) else Triple(hp, vp + 1, total + cost * hp) }.third }